1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
22	    @Mapping(target = "displayName",
23	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "locality", expression = "java(locality(owner))")
26	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
27	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
28	    @Mapping(target = "membershipPoints",
29	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerMembership.points(owner))")
30	    @Mapping(target = "membershipLevel",
31	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerMembership.level(owner))")
32	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
33	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
34	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
35	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
36	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
37	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
38	    @Mapping(target = "riskFlag", expression = "java(riskFlag(owner))")
39	    OwnerDto toOwnerDto(Owner owner);
40	
41	    /**
42	     * The owner's {@code riskFlag}: true when any of these hold — the owner is a possible duplicate
43	     * ({@code possibleDuplicate} true), the email domain is disposable-adjacent (see
44	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerEmail#isDisposableAdjacent}),
45	     * or the city is over its soft capacity ({@code capacityWarning} true); otherwise false.
46	     */
47	    default boolean riskFlag(Owner owner) {
48	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
49	                || Boolean.TRUE.equals(owner.getCapacityWarning())
50	                || org.springframework.samples.petclinic.rest.function.owner.OwnerEmail
51	                        .isDisposableAdjacent(owner.getEmail());
52	    }
53	
54	    /**
55	     * The owner's canonical URL, formatted {@code '/api/owners/<id>'} where id is the owner's id.
56	     * Null when the owner has no id yet.
57	     */
58	    default String selfLink(Owner owner) {
59	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
60	    }
61	
62	    /**
63	     * The owner's stored E.164 {@code telephone} formatted for humans: the '+' country code, a space,
64	     * then the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). Null when no
65	     * telephone is recorded.
66	     */
67	    default String telephoneDisplay(Owner owner) {
68	        return org.springframework.samples.petclinic.rest.function.owner.OwnerTelephone.toDisplay(
69	                owner.getTelephone());
70	    }
71	
72	    /**
73	     * The owner's age band, computed from {@code birthDate} against {@code registrationDate}:
74	     * {@code MINOR} (under 18), {@code ADULT} (18-64) or {@code SENIOR} (65+). Null when no
75	     * birth date is recorded.
76	     */
77	    default String ageBand(Owner owner) {
78	        if (owner.getBirthDate() == null) {
79	            return null;
80	        }
81	        java.time.LocalDate reference = owner.getRegistrationDate() != null
82	                ? owner.getRegistrationDate() : java.time.LocalDate.now();
83	        int age = java.time.Period.between(owner.getBirthDate(), reference).getYears();
84	        if (age < 18) {
85	            return "MINOR";
86	        }
87	        if (age < 65) {
88	            return "ADULT";
89	        }
90	        return "SENIOR";
91	    }
92	
93	    /**
94	     * The owner's derived {@code identityKey} = SHA-256 hex over
95	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, the single key all
96	     * duplicate detection is expressed through.
97	     */
98	    default String identityKey(Owner owner) {
99	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(
100	                owner.getTelephone(), owner.getEmail(), owner.getLastName());
101	    }
102	
103	    /**
104	     * The owner's segment, formatted {@code '<TIER>_<AREA>'}: one of {@code PREMIUM_METRO},
105	     * {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}. TIER is
106	     * {@code PREMIUM} when membershipLevel is 3 or more, otherwise {@code STANDARD}. AREA is
107	     * {@code METRO} when the locality is a known region (NSW, VIC or QLD), otherwise {@code REGIONAL}.
108	     */
109	    default String ownerSegment(Owner owner) {
110	        String tier = org.springframework.samples.petclinic.rest.function.owner.OwnerMembership
111	                .level(owner) >= 3 ? "PREMIUM" : "STANDARD";
112	        String locality = locality(owner);
113	        boolean metro = "NSW".equals(locality) || "VIC".equals(locality) || "QLD".equals(locality);
114	        return tier + "_" + (metro ? "METRO" : "REGIONAL");
115	    }
116	
117	    /**
118	     * The owner's preferred contact channel: {@code EMAIL} when an email is present, otherwise
119	     * {@code PHONE}.
120	     */
121	    default String contactPreference(Owner owner) {
122	        return owner.getEmail() != null && !owner.getEmail().isBlank() ? "EMAIL" : "PHONE";
123	    }
124	
125	    /**
126	     * The owner's salutation: the honorific {@code title}, a single space, then the {@code lastName}
127	     * when a title is present, or just the {@code lastName} when no title is given.
128	     */
129	    default String salutation(Owner owner) {
130	        String title = owner.getTitle();
131	        if (title == null || title.isBlank()) {
132	            return owner.getLastName();
133	        }
134	        return title + " " + owner.getLastName();
135	    }
136	
137	    default String initials(Owner owner) {
138	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
